{
  "name": "Deploy accepted DemandRift backend revision",
  "permissions": {
    "contents": "read",
    "actions": "read"
  },
  "concurrency": {
    "group": "demandrift-api-deploy",
    "cancel-in-progress": false
  },
  "jobs": {
    "build": {
      "if": "github.ref == 'refs/heads/main'",
      "runs-on": "ubuntu-latest",
      "timeout-minutes": 35,
      "steps": [
        {
          "name": "Require exact main revision and successful API CI",
          "env": {
            "GH_TOKEN": "${{ github.token }}",
            "RELEASE_SHA": "${{ inputs.release_sha }}",
            "ACCEPTANCE_RUN": "${{ inputs.acceptance_run }}",
            "REPOSITORY": "${{ github.repository }}"
          },
          "shell": "bash",
          "run": "set -euo pipefail\nif [[ ! \"$RELEASE_SHA\" =~ ^[0-9a-f]{40}$ ]]; then exit 64; fi\nif [[ ! \"$ACCEPTANCE_RUN\" =~ ^[a-zA-Z0-9][a-zA-Z0-9_-]{0,127}$ ]]; then exit 64; fi\nmain_sha=$(gh api \"repos/$REPOSITORY/git/ref/heads/main\" --jq '.object.sha')\ntest \"$main_sha\" = \"$RELEASE_SHA\"\ngh api \"repos/$REPOSITORY/actions/workflows/api-ci.yml/runs?head_sha=$RELEASE_SHA&branch=main&per_page=100\" > \"$RUNNER_TEMP/api-checks.json\"\npython3 - \"$RUNNER_TEMP/api-checks.json\" <<'PY'\nimport json, os, sys\nruns = json.load(open(sys.argv[1]))[\"workflow_runs\"]\nmatching = [r for r in runs if r[\"head_sha\"] == os.environ[\"RELEASE_SHA\"]\n            and r[\"head_branch\"] == \"main\" and r[\"event\"] in (\"push\", \"workflow_dispatch\")]\nif not matching:\n    raise SystemExit(\"API CI has not run for the accepted revision\")\nlatest = max(matching, key=lambda c: c[\"id\"])\nif latest[\"status\"] != \"completed\" or latest[\"conclusion\"] != \"success\":\n    raise SystemExit(\"API CI did not pass\")\nPY\nprintf 'Deploying accepted revision %s from run %s\\n' \"$RELEASE_SHA\" \"$ACCEPTANCE_RUN\"\n"
        },
        {
          "name": "Test, build and deploy exact main API commit on Hetzner",
          "env": {
            "BUILD_KEY": "${{ secrets.HETZNER_BUILD_SSH_KEY }}",
            "KNOWN_HOSTS": "${{ secrets.HETZNER_BUILD_KNOWN_HOSTS }}",
            "TARGET": "${{ vars.HETZNER_BUILD_HOST }}",
            "COMMIT": "${{ inputs.release_sha }}"
          },
          "shell": "bash",
          "run": "set -euo pipefail\ntest -n \"$BUILD_KEY\" && test -n \"$KNOWN_HOSTS\" && test -n \"$TARGET\"\ntemp_dir=$(mktemp -d)\ntrap 'rm -rf \"$temp_dir\"' EXIT\numask 077\nprintf '%s\\n' \"$BUILD_KEY\" > \"$temp_dir/key\"\nprintf '%s\\n' \"$KNOWN_HOSTS\" > \"$temp_dir/known_hosts\"\nssh -F /dev/null -i \"$temp_dir/key\" \\\n  -o BatchMode=yes -o IdentitiesOnly=yes -o StrictHostKeyChecking=yes \\\n  -o UserKnownHostsFile=\"$temp_dir/known_hosts\" \\\n  -o ConnectTimeout=20 -o ServerAliveInterval=15 -o ServerAliveCountMax=4 \\\n  \"root@$TARGET\" \"build-api $COMMIT\"\n"
        }
      ]
    }
  },
  "on": {
    "workflow_dispatch": {
      "inputs": {
        "release_sha": {
          "description": "Exact main revision accepted for backend deployment",
          "required": true,
          "type": "string"
        },
        "acceptance_run": {
          "description": "Persistent orchestrator run whose release gates passed",
          "required": true,
          "type": "string"
        }
      }
    }
  }
}

